Generated Query:
PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?policyNumber ?premiumAmount
       (COUNT(DISTINCT ?claim) AS ?numberOfClaims)
       (SUM(?claimTotalLoss) AS ?totalLoss)
       ((SUM(?claimTotalLoss) / ?premiumAmount) AS ?lossRatio)
WHERE {
  SERVICE <mapped> {
    ?pcd a in:PolicyCoverageDetail ;
         in:hasPolicy ?policy ;
         in:hasPremiumAmount ?premium .

    ?policy in:policyNumber ?policyNumber .

    ?premium in:premiumAmount ?premiumAmount .

    ?claim a in:Claim ;
           in:against ?pcd .

    OPTIONAL {
      SELECT ?claim (SUM(xsd:decimal(?lpa)) AS ?sumLossPayment)
      WHERE {
        ?claim in:hasLossPayment ?lp .
        ?lp in:lossPaymentAmount ?lpa .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(xsd:decimal(?lra)) AS ?sumLossReserve)
      WHERE {
        ?claim in:hasLossReserve ?lr .
        ?lr in:lossReserveAmount ?lra .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(xsd:decimal(?epa)) AS ?sumExpensePayment)
      WHERE {
        ?claim in:hasExpensePayment ?ep .
        ?ep in:expensePaymentAmount ?epa .
      }
      GROUP BY ?claim
    }

    OPTIONAL {
      SELECT ?claim (SUM(xsd:decimal(?era)) AS ?sumExpenseReserve)
      WHERE {
        ?claim in:hasExpenseReserve ?er .
        ?er in:expenseReserveAmount ?era .
      }
      GROUP BY ?claim
    }

    BIND(
      COALESCE(?sumLossPayment, 0) +
      COALESCE(?sumLossReserve, 0) +
      COALESCE(?sumExpensePayment, 0) +
      COALESCE(?sumExpenseReserve, 0)
      AS ?claimTotalLoss
    )
  }
}
GROUP BY ?policyNumber ?premiumAmount
ORDER BY ?policyNumber

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?policyHolder ?policyHolderId (SUM(?amount) AS ?totalPremiumPaid)
WHERE {
  SERVICE <mapped> {
    ?policy in:hasPolicyHolder ?policyHolder .
    ?policyCoverageDetail in:hasPolicy ?policy ;
                          in:hasPremiumAmount ?premium .
    ?premium in:premiumAmount ?amount .

    OPTIONAL { ?policyHolder in:policyHolderId ?policyHolderId . }
  }
}
GROUP BY ?policyHolder ?policyHolderId

PREFIX in: <http://data.world/schema/insurance/>

SELECT ?agentId (COUNT(DISTINCT ?policy) AS ?policyCount)
WHERE {
  SERVICE <mapped> {
    ?policy a in:Policy ;
            in:soldByAgent ?agent .
    ?agent in:agentId ?agentId .
  }
}
GROUP BY ?agentId
ORDER BY ?agentId

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber ?openDate ?closeDate
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber ;
           in:claimOpenDate ?openDate .
    OPTIONAL { ?claim in:claimCloseDate ?closeDate . }
  }
}
ORDER BY ?claimNumber

PREFIX in: <http://data.world/schema/insurance/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?claimNumber
       (COALESCE(SUM(xsd:decimal(?lossPaymentAmt)), 0) +
        COALESCE(SUM(xsd:decimal(?lossReserveAmt)), 0) +
        COALESCE(SUM(xsd:decimal(?expensePaymentAmt)), 0) +
        COALESCE(SUM(xsd:decimal(?expenseReserveAmt)), 0) AS ?totalLoss)
WHERE {
  SERVICE <mapped> {
    ?claim a in:Claim ;
           in:claimNumber ?claimNumber .

    OPTIONAL {
      ?claim in:hasLossPayment ?lp .
      ?lp in:lossPaymentAmount ?lossPaymentAmt .
    }
    OPTIONAL {
      ?claim in:hasLossReserve ?lr .
      ?lr in:lossReserveAmount ?lossReserveAmt .
    }
    OPTIONAL {
      ?claim in:hasExpensePayment ?ep .
      ?ep in:expensePaymentAmount ?expensePaymentAmt .
    }
    OPTIONAL {
      ?claim in:hasExpenseReserve ?er .
      ?er in:expenseReserveAmount ?expenseReserveAmt .
    }
  }
}
GROUP BY ?claimNumber
